<?php
require_once __DIR__.'/config/app.php';require_login();$uid=(int)$_SESSION['user_id'];$selected=(int)($_GET['lost_id']??0);$s=mysqli_prepare($conn,"SELECT * FROM items WHERE user_id=? AND type='lost' AND status='active' ORDER BY created_at DESC");mysqli_stmt_bind_param($s,'i',$uid);mysqli_stmt_execute($s);$lr=mysqli_stmt_get_result($s);$lost=[];while($x=mysqli_fetch_assoc($lr))$lost[]=$x;$current=null;$matches=[];
if($selected){$s=mysqli_prepare($conn,"SELECT * FROM items WHERE id=? AND user_id=? AND type='lost' AND status='active'");mysqli_stmt_bind_param($s,'ii',$selected,$uid);mysqli_stmt_execute($s);$rr=mysqli_stmt_get_result($s);if(mysqli_num_rows($rr)===1){$current=mysqli_fetch_assoc($rr);$f=mysqli_prepare($conn,"SELECT items.*,users.full_name FROM items INNER JOIN users ON users.id=items.user_id WHERE items.type='found' AND items.status='active' AND items.category=? AND items.user_id!=? ORDER BY items.created_at DESC");mysqli_stmt_bind_param($f,'si',$current['category'],$uid);mysqli_stmt_execute($f);$fr=mysqli_stmt_get_result($f);while($m=mysqli_fetch_assoc($fr)){$score=40;$a=strtolower(trim($current['location']));$b=strtolower(trim($m['location']));if($a===$b)$score+=25;elseif(str_contains($a,$b)||str_contains($b,$a))$score+=15;$days=abs((strtotime($current['item_date'])-strtotime($m['item_date']))/86400);if($days<=3)$score+=20;elseif($days<=7)$score+=10;similar_text(strtolower($current['item_name']),strtolower($m['item_name']),$sim);$score+=(int)round(($sim/100)*15);$m['match_score']=min(100,$score);$matches[]=$m;}usort($matches,fn($a,$b)=>$b['match_score']<=>$a['match_score']);}}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Possible Matches - UniFind</title><link rel="stylesheet" href="css/style.css"></head><body><nav class="navbar"><a class="brand" href="dashboard.php">UniFind</a><div class="nav-actions"><a class="btn btn-small btn-secondary" href="dashboard.php">Dashboard</a><a class="btn btn-small" href="logout.php">Logout</a></div></nav><main class="page-container"><section class="page-heading"><div><span class="eyebrow">Smart Matching</span><h1>Possible Matches</h1><p>Select one of your active lost reports to compare it with found items.</p></div></section><?php if(count($lost)):?><form class="match-selector" method="get"><select name="lost_id" required><option value="">Select Your Lost Item</option><?php foreach($lost as $l):?><option value="<?=(int)$l['id']?>" <?=$selected===(int)$l['id']?'selected':''?>><?=e($l['item_name'])?> - <?=e($l['location'])?></option><?php endforeach;?></select><button class="btn">Find Matches</button></form><?php else:?><div class="empty-state"><h3>No active lost reports</h3><p>Report a lost item before using smart matching.</p><a class="btn" href="report-lost.php">Report Lost Item</a></div><?php endif;?><?php if($current):?><section class="selected-report"><span class="status-pill lost-pill">LOOKING FOR</span><h2><?=e($current['item_name'])?></h2><p><?=e($current['location'])?> · <?=e($current['item_date'])?> · <?=e($current['category'])?></p></section><div class="section-heading"><div><h2>Suggested Found Items</h2><p>Scores use category, location, date and item-name similarity.</p></div></div><?php if(count($matches)):?><section class="item-grid"><?php foreach($matches as $m):?><article class="item-card"><?php if($m['image']&&is_file(__DIR__.'/uploads/'.$m['image'])):?><img class="item-image" src="uploads/<?=e($m['image'])?>" alt=""><?php else:?><div class="item-image placeholder">No Image Available</div><?php endif;?><div class="item-card-body"><div class="card-topline"><span class="match-score"><?=(int)$m['match_score']?>% MATCH</span><span class="status-pill found-pill">FOUND</span></div><h3><?=e($m['item_name'])?></h3><p class="item-description"><?=e($m['description'])?></p><div class="detail-list"><span><strong>Location:</strong> <?=e($m['location'])?></span><span><strong>Date:</strong> <?=e($m['item_date'])?></span><span><strong>Reported by:</strong> <?=e($m['full_name'])?></span></div><a class="btn btn-block" href="claim-item.php?id=<?=(int)$m['id']?>">Claim Item</a></div></article><?php endforeach;?></section><?php else:?><div class="empty-state"><h3>No possible matches yet</h3><p>No active found items in the same category are currently available.</p></div><?php endif;?><?php endif;?></main><script src="js/ui-effects.js"></script></body></html>